entries[3963] = { ["name"] = "Kompaktes Ernteschnitterset", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenstrebe (2), Bronzegerüst , Gyrochronatom (2), Schweres Leder (4)\n30\nBenötigt Ingenieurskunst\n(175)\nBenutzen: Stellt einen kompakten Ernteschnitter her, der 10 Minuten lang oder bis zu seiner Zerstörung für Euch kämpft. (10 Min Abklingzeit)" }
entries[3965] = { ["name"] = "Hochentwickelte Zielattrappe", ["text"] = "Wirken in 12.5 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nEisenstrebe , Bronzegerüst , Gyrochronatom , Schweres Leder (4)\nBenötigt Ingenieurskunst\n(185)\nBenutzen: Lässt eine Zielattrappe auf den Boden fallen, die in der Nähe befindliche Monster dazu bringt, sie anzugreifen. Die Attrappe bleibt bis zu ihrer Zerstörung aktiv, maximal jedoch für 15 Sekunden. (2 Min Abklingzeit)" }
